338: func (s *Service) openGreenhousePane(ctx context.Context, task store.Task) (string, error) {
339: 	snapshot, err := s.snapshot(ctx)
340: 	if err != nil {
341: 		return "", err
342: 	}
343: 	for _, pane := range snapshot.Panes {
344: 		if pane.WorkspaceID == task.HerdrWorkspaceID && filepath.Clean(pane.CWD) == filepath.Clean(task.WorktreePath) && pane.PaneID != task.PaneID && strings.Contains(pane.Label, "greenhouse") {
345: 			return pane.PaneID, nil
346: 		}
347: 	}
348: 	raw, err := s.herdrCall(ctx, "pane.split", map[string]any{"target_pane_id": task.PaneID, "direction": "right", "cwd": task.WorktreePath, "focus": false})
349: 	if err != nil {
350: 		return "", err
351: 	}
352: 	var result struct {
353: 		Pane struct {
354: 			PaneID string `json:"pane_id"`
355: 		} `json:"pane"`
356: 	}
357: 	if json.Unmarshal(raw, &result) != nil || result.Pane.PaneID == "" {
358: 		return "", fmt.Errorf("herdr did not return the Greenhouse pane")
359: 	}
360: 	paneID := result.Pane.PaneID
361: 	if _, err := s.herdrCall(ctx, "pane.rename", map[string]any{"pane_id": paneID, "label": "greenhouse:" + task.PaneLabel}); err != nil {
362: 		return "", err
363: 	}
364: 	if _, err := s.herdrCall(ctx, "pane.send_input", map[string]any{"pane_id": paneID, "text": "greenhouse", "keys": []string{"enter"}}); err != nil {
365: 		return "", err
366: 	}
367: 	return paneID, nil
368: }
